3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the new owner's deterministic {@code householdId} (see {@link Households}),
8	 * derived from its last name and postcode, so every owner that shares a last name and
9	 * postcode resolves to the same stable value automatically — no coordination and no
10	 * opt-in required. An owner with no postcode gets no household id. Runs after
11	 * {@link BuildOwner} (so the entity, its name and postcode exist) and before the household
12	 * duplicate check ({@link EnsureUniqueHousehold}) and {@link SaveOwner}, both of which key
13	 * off this value.
14	 */
15	public class AssignHouseholdId {
16	
17	    public void service(@Val Owner owner) {
18	        owner.setHouseholdId(Households.idFor(owner.getLastName(), owner.getPostcode()));
19	    }
20	}
