1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records the new owner's {@code householdSize}: the number of owners in its household
9	 * (same last name and postcode, hence the same {@code householdId}, see {@link Households})
10	 * once this owner is added — the existing household members plus the new owner itself. Runs
11	 * after {@link BuildOwner} (so the entity, its name and postcode exist) and before
12	 * {@link SaveOwner} persists the count, so the freshly created owner is counted exactly
13	 * once.
14	 */
15	public class AssignOwnerHouseholdSize {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        int existing = Households.membersOf(ownerRepository, owner.getLastName(), owner.getPostcode()).size();
19	        owner.setHouseholdSize(existing + 1);
20	    }
21	}
