10	/**
11	 * Flags a soft duplicate. A new owner that reaches this step is not blocked by the
12	 * household duplicate check ({@link EnsureUniqueHousehold}) — either it has no existing
13	 * household member, or it opted in with {@code sharesHousehold}. A declared member is a
14	 * genuine household member, not a suspected duplicate, so it is never flagged here. Any
15	 * other owner that shares an existing owner's household (same last name and postcode, hence
16	 * the same {@code householdId}, see {@link Households}) but differs in telephone is created
17	 * anyway and marked as a possible duplicate of that owner. Runs before {@link SaveOwner}
18	 * persists the flags; when several match, the earliest (lowest id) is recorded. An owner
19	 * with no postcode has no household and can never be a possible duplicate.
20	 */
21	public class AssignOwnerPossibleDuplicate {
22	
23	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
24	        if (owner.getHouseholdId() == null || Boolean.TRUE.equals(request.getSharesHousehold())) {
25	            return;
26	        }
27	        Households.membersOf(ownerRepository, owner.getLastName(), owner.getPostcode()).stream()
28	                .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
29	                .min(Comparator.comparingInt(Owner::getId))
30	                .ifPresent(match -> {
31	                    owner.setPossibleDuplicate(true);
32	                    owner.setPossibleDuplicateOf(match.getId());
33	                });
34	    }
35	}
