31	    Owner toOwner(OwnerFieldsDto ownerDto);
32	
33	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
34	
35	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
36	
37	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
