132	    public String getAddress() {
133	        return this.address;
134	    }
135	
136	    public void setAddress(String address) {
137	        this.address = address;
138	    }
139	
140	    /**
141	     * The first line of the owner's structured address, in normalized form, or null when the
142	     * owner was created from the flat {@link #getAddress() address} only. The composed
143	     * {@code address} is derived from this and {@link #getAddressLine2()}.
144	     */
145	    public String getAddressLine1() {
146	        return this.addressLine1;
147	    }
148	
149	    public void setAddressLine1(String addressLine1) {
150	        this.addressLine1 = addressLine1;
151	    }
152	
153	    /**
154	     * The optional second line of the owner's structured address, in normalized form, or null
155	     * when absent or when the owner was created from the flat {@link #getAddress() address}.
156	     */
157	    public String getAddressLine2() {
158	        return this.addressLine2;
159	    }
160	
161	    public void setAddressLine2(String addressLine2) {
162	        this.addressLine2 = addressLine2;
163	    }
164	
165	    public String getCity() {
166	        return this.city;
167	    }
168	
169	    public void setCity(String city) {
170	        this.city = city;
171	    }
172	
173	    public String getTelephone() {
174	        return this.telephone;
175	    }
176	
177	    public void setTelephone(String telephone) {
178	        this.telephone = telephone;
179	    }
180	
181	    /**
182	     * The stored E.164 telephone formatted for humans: the country code, a space, then the
183	     * national digits grouped in threes (e.g. {@code "+61 412 345 678"}), while
184	     * {@link #getTelephone()} keeps the raw E.164 form. Derived from stored state, never
185	     * persisted.
186	     */
187	    public String getTelephoneDisplay() {
188	        return E164PhoneNumber.toDisplay(this.telephone);
189	    }
190	
191	    public String getEmail() {
192	        return this.email;
193	    }
194	
195	    public void setEmail(String email) {
196	        this.email = email;
197	    }
198	
199	    /**
200	     * The owner's postcode: a 4-digit code that, when supplied at creation, is validated
201	     * against the city's region and then stored verbatim. Optional, so may be null.
202	     */
203	    public String getPostcode() {
204	        return this.postcode;
205	    }
206	
207	    public void setPostcode(String postcode) {
208	        this.postcode = postcode;
209	    }
210	
211	    public LocalDate getRegistrationDate() {
212	        return this.registrationDate;
213	    }
214	
215	    public void setRegistrationDate(LocalDate registrationDate) {
216	        this.registrationDate = registrationDate;
217	    }
218	
219	    /**
220	     * The owner's date of birth. Optional, so may be null.
221	     */
222	    public LocalDate getBirthDate() {
223	        return this.birthDate;
224	    }
225	
226	    public void setBirthDate(LocalDate birthDate) {
227	        this.birthDate = birthDate;
228	    }
229	
230	    /**
231	     * The owner's age band as at registration: {@code "MINOR"} for under 18,
232	     * {@code "ADULT"} for 18 to 64, or {@code "SENIOR"} for 65 and over, measured from the
233	     * birth date against the registration date. Null when no birth date is recorded.
234	     * Derived from stored state, never persisted.
235	     */
236	    public String getAgeBand() {
237	        if (this.birthDate == null || this.registrationDate == null) {
238	            return null;
239	        }
240	        return AgeBand.of(this.birthDate, this.registrationDate);
241	    }
242	
