266	        return this.namesakeCount;
267	    }
268	
269	    public void setNamesakeCount(Integer namesakeCount) {
270	        this.namesakeCount = namesakeCount;
271	    }
272	
273	    public Integer getHouseholdSize() {
274	        return this.householdSize;
275	    }
276	
277	    public void setHouseholdSize(Integer householdSize) {
278	        this.householdSize = householdSize;
279	    }
280	
281	    public String getMembershipNumber() {
282	        return this.membershipNumber;
283	    }
284	
285	    public void setMembershipNumber(String membershipNumber) {
286	        this.membershipNumber = membershipNumber;
287	    }
288	
289	    /**
290	     * Whether this owner was created as part of a bulk signup: {@code true} when more
291	     * than 80 owners had already been registered on this owner's registration date at
292	     * the moment it was created, {@code false} otherwise. Captured at creation.
293	     */
294	    public boolean isBulkSignupWarning() {
295	        return this.bulkSignupWarning;
296	    }
297	
298	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
299	        this.bulkSignupWarning = bulkSignupWarning;
300	    }
301	
302	    /**
303	     * Whether this owner resembles an existing one: {@code true} when, at creation, it
304	     * shared an existing owner's household (same last name and postcode, hence the same
305	     * {@link #getHouseholdId() household id}) while having a different telephone and was not
306	     * a declared household member, {@code false} otherwise. A declared member (created with
307	     * {@code sharesHousehold}) is a genuine member, not a suspected duplicate. When true,
308	     * {@link #getPossibleDuplicateOf()} holds that owner's id. Captured at creation.
309	     */
310	    public boolean isPossibleDuplicate() {
311	        return this.possibleDuplicate;
312	    }
313	
314	    public void setPossibleDuplicate(boolean possibleDuplicate) {
315	        this.possibleDuplicate = possibleDuplicate;
316	    }
317	
318	    /**
319	     * The id of the existing owner this owner possibly duplicates (same household — last
320	     * name and postcode — different telephone), or null when it is not a possible
321	     * duplicate. Captured at creation.
322	     */
323	    public Integer getPossibleDuplicateOf() {
324	        return this.possibleDuplicateOf;
325	    }
326	
327	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
328	        this.possibleDuplicateOf = possibleDuplicateOf;
329	    }
330	
331	    /**
332	     * Whether this owner has been soft-deleted: {@code true} once a {@code DELETE} has
333	     * flagged the record (which is retained rather than removed), {@code false} for a live
334	     * owner. A newly created owner is not deleted. A deleted owner is still returned by
335	     * {@code GET}, but is ignored by the create endpoint's duplicate and identity checks.
336	     */
337	    public boolean isDeleted() {
338	        return this.deleted;
339	    }
340	
341	    public void setDeleted(boolean deleted) {
342	        this.deleted = deleted;
343	    }
344	
345	    /**
346	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
347	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
348	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
349	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
350	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
351	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
352	     * region is derived directly from the stored postcode and city. Derived from stored
353	     * state, never persisted.
354	     */
355	    public String getLocality() {
356	        String region = CustomerCode.regionOf(this.customerCode);
357	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
358	    }
359	
360	    /**
361	     * The owner's timezone: the IANA name for this owner's {@link #getLocality() locality}
362	     * via the fixed region-to-timezone table (NSW->Australia/Sydney,
363	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null} when the region
364	     * has no known timezone. Derived from stored state, never persisted.
365	     */
366	    public String getTimezone() {
367	        return RegionTimezone.forRegion(getLocality());
368	    }
369	
370	    /**
371	     * The owner's membership points, from 0 upwards: starts at 0, gains 2 when this owner
372	     * has an email address, gains 1 when this owner had no namesakes at creation
373	     * ({@code namesakeCount} is 0), gains 2 when this owner's household has 3 or more
374	     * members, and gains 3 once this owner's tenure spans at least one elapsed fiscal year.
375	     * A newly created owner has zero tenure, so it never earns those points at creation.
376	     * Derived from stored state, never persisted.
377	     */
378	    public int getMembershipPoints() {
379	        int points = 0;
380	        if (hasEmail()) {
381	            points += 2;
382	        }
383	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
384	            points += 1;
385	        }
386	        if (this.householdSize != null && this.householdSize >= 3) {
387	            points += 2;
388	        }
389	        if (getTenureFiscalYears() >= 1) {
390	            points += 3;
391	        }
392	        return points;
393	    }
394	
395	    /**
396	     * The owner's fiscal year: the {@code FY<YY>} label (fiscal year starting 1 July,
397	     * identified by its ending calendar year) of the {@code registrationDate}, or
398	     * {@code null} when no registration date is recorded. Derived from stored state, never
399	     * persisted.
400	     */
401	    public String getFiscalYear() {
402	        return this.registrationDate == null ? null : FiscalYear.labelOf(this.registrationDate);
403	    }
404	
405	    /**
406	     * The owner's membership level, from 1 to 4: derived from {@link #getMembershipPoints()}
407	     * as level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Derived from
408	     * stored state, never persisted.
409	     */
410	    public int getMembershipLevel() {
411	        int points = getMembershipPoints();
412	        if (points <= 1) {
413	            return 1;
414	        }
415	        if (points <= 3) {
416	            return 2;
417	        }
418	        if (points <= 5) {
419	            return 3;
420	        }
421	        return 4;
422	    }
423	
424	    /**
425	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each
426	     * starting 1 July) between the {@code registrationDate} and the current server date, or
427	     * 0 when no registration date is recorded. Never negative in practice, since a future
428	     * registration date is rejected at creation.
429	     */
430	    private int getTenureFiscalYears() {
431	        if (this.registrationDate == null) {
432	            return 0;
433	        }
434	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
435	    }
436	
437	    /**
438	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of
439	     * the {@code customerCode}. Derived from stored state, never persisted.
440	     */
441	    public int getCheckDigit() {
442	        return LuhnCheckDigit.of(this.customerCode);
443	    }
444	
445	    /**
446	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
447	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
448	     */
449	    public String getContactPreference() {
450	        return hasEmail() ? "EMAIL" : "PHONE";
451	    }
452	
453	    /**
454	     * The owner's identity key: a composite fingerprint formed as the normalized telephone,
455	     * the email (or empty when absent) and the household id (or empty when none), joined by
456	     * {@code '|'}. Derived from stored state, never persisted.
457	     */
458	    public String getIdentityKey() {
459	        String emailPart = hasEmail() ? this.email : "";
460	        String householdPart = this.householdId == null ? "" : this.householdId;
461	        return this.telephone + "|" + emailPart + "|" + householdPart;
462	    }
463	
464	    private boolean hasEmail() {
465	        return this.email != null && !this.email.isEmpty();
466	    }
467	
468	    protected Set<Pet> getPetsInternal() {
469	        if (this.pets == null) {
470	            this.pets = new HashSet<>();
471	        }
472	        return this.pets;
473	    }
474	
475	    protected void setPetsInternal(Set<Pet> pets) {
476	        this.pets = pets;
477	    }
478	
479	    public List<Pet> getPets() {
480	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
481	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
482	        return Collections.unmodifiableList(sortedPets);
483	    }
484	
485	    public void setPets(List<Pet> pets) {
486	        this.pets = new HashSet<>(pets);
487	    }
488	
489	    public void addPet(Pet pet) {
490	        getPetsInternal().add(pet);
491	        pet.setOwner(this);
492	    }
493	
494	    /**
495	     * Return the Pet with the given name, or null if none found for this Owner.
496	     *
497	     * @param name to test
498	     * @return true if pet name is already in use
499	     */
500	    public Pet getPet(String name) {
501	        return getPet(name, false);
502	    }
503	
504	    /**
505	     * Return the Pet with the given name, or null if none found for this Owner.
506	     *
507	     * @param name to test
508	     * @return true if pet name is already in use
509	     */
510	    public Pet getPet(String name, boolean ignoreNew) {
511	        name = name.toLowerCase();
512	        for (Pet pet : getPetsInternal()) {
513	            if (!ignoreNew || !pet.isNew()) {
514	                String compName = pet.getName();
515	                compName = compName.toLowerCase();
516	                if (compName.equals(name)) {
517	                    return pet;
518	                }
519	            }
520	        }
521	        return null;
522	    }
523	
524	    public Pet getPet(Integer petId) {
525	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
526	    }
527	
528	    @Override
529	    public String toString() {
530	        return new ToStringCreator(this)
531	
532	            .append("id", this.getId())
533	            .append("new", this.isNew())
534	            .append("lastName", this.getLastName())
535	            .append("firstName", this.getFirstName())
536	            .append("address", this.address)
537	            .append("city", this.city)
538	            .append("telephone", this.telephone)
539	            .toString();
540	    }
541	}
